head.script:
		    var currIndex = 0;                                           // 현재 행 ( 그리드내에서 탭키 이벤트시 다음행으로 이동 처리)
		    var fnExistMaxDate = ""; 
		    
           /**************************************************************************
            * function    : init
            * Description : 서브 메인 화면 초기화
            * Parameter   : 
            * Return      : 
            **************************************************************************/
	        function init() {
				this.document.title=divisionNm;
				gridDataSearch();
				resizeIframe();
			}

        	/**************************************************************************
             * function    : callBack
             * Description : submission 실행 후 Callback
             * Parameter   : retAction(submission 실행 Action), rowCount(조회 목록 총 건수)
             * Return      : null
             **************************************************************************/
        	function callBack(svcId,fnId,strResp) {   
				var arrObjNm = getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/objNm").split("^");
				
				if (svcId == "BISComStatisticsLinkSO") {
					var arr = WebSquare.ModelUtil.findInstanceNodes( "respOutForm/root/message/BISComMetaDataDTO/BISComStatisticsLinkListDTO/BISComStatisticsLinkDTO" );
					(arr.length > 0) ? setScreen() : showMsg("C_I028","그리드 속성 정보");
				} else if (svcId == arrObjNm[1]) {
					if( fnId == arrObjNm[2] ){
						var gridXml = getInstanceNode("resp/root/message/BISComDspDatListDTO");
						if (getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/summaryRowCnt") > 0) 
							gridXml = setSubTotalData(grdMain);							
						grdMain.setXML( gridXml );
						
						// 그리드 좌상단 라벨 처리 추가
						if(typeof setGrdLabel == "function"){
							setGrdLabel();
						}
						
						if (getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/chartTyp") != "") 
							chartShow();							
						changeGridColumnPropery(grdMain);  // 셀 컬러 수정
						
						resizeIframe();	
						
					//}else if( fnId == "getExistMaxDate"){
					}else if( fnId == fnExistMaxDate){
						existMaxDate = getValue("respMaxDate/root/message/BISComDspDatDTO/val1");
					}
				
				} else if (svcId == "MGMTComBookMarkSO") {
					parent.callBack(svcId,fnId,strResp);
				}
            }

        	/**************************************************************************
             * function    : getExistMaxDate
             * Description : 공통화면에서 조회기간 설정을 위하여 데이터가 존재하는 날짜를 구함
             * Parameter   : 
             * Return      : 데이터가 존재하는 MAX 날짜
             **************************************************************************/			
			function getExistMaxDate(fn){
				/* 같은 SO에 2개의 화면이 있을 경우getExistMaxDate(함수명) 형태로 함수명을 파라미터로 전달. */
				if(fn == undefined) fnExistMaxDate = "getExistMaxDate";
				else fnExistMaxDate = fn;
				
				var arrObjNm = getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/objNm").split("^"); 
	       	    if ( arrObjNm[0] == "" || arrObjNm == null || arrObjNm == undefined )  {
		       	    showMsg("C_I034");
		       	    return;
	       	    }
	       	    var BISComDspDatDTO = {BISComDspDatDTO:{}};
		        callProFrame(arrObjNm[0],arrObjNm[1],fnExistMaxDate,BISComDspDatDTO, "BISComDspDatDTO","respMaxDate");
			}
			
            /**************************************************************************
             * function    : searchFormReading
             * Description : 조회 폼, Footer 폼 로딩
             * Parameter   : searchForm(조회조건 폼 경로), footerForm(Footer폼 경로)
             * Return      : null
             **************************************************************************/
        	function searchFormReading(searchForm, footerForm) {
	       	    if (searchForm == "") {
	       	    	wfrmSearch.setStyle( "display" , "none" );
	       	    } else {
		       	    wfrmSearch.setStyle( "display" , "block" );
		       	    wfrmSearch.setSrc( searchForm );
	       	    }   
	       	    
	       	    if (footerForm == "") {
	       	    	wfrmFooter.setStyle( "display" , "none" );
	       	    } else {
		       	    wfrmFooter.setStyle( "display" , "block" );
		       	    wfrmFooter.setSrc(footerForm );
	       	    }
        	}     
        	
            /**************************************************************************
             * function    : gridDataSearch
             * Description : 화면 구성 정보를 조회
             * Parameter   : null
             * Return      : null
             **************************************************************************/	
        	function gridDataSearch() {
	            WebSquare.ModelUtil.removeChildNodes( "BISComMetaDataDTO" );
		        setValue("BISComMetaDataDTO/divisionId", divisionId);
		        var BISComMetaDataDTO =  {"BISComMetaDataDTO":{}};
		        callProFrame("BIS-COM","BISComStatisticsLinkSO","selectMetaInfoAdvanced",BISComMetaDataDTO, "BISComMetaDataDTO","respOutForm");
        	}
        	
            /**************************************************************************
             * function    : searchData
             * Description : 자료 조회
             * Parameter   : 페이지 리스트 일 경우에만 적용 startRow(검색 시작행), rowCount(그리드에 보여질 row 수)
             * Return      : null
             **************************************************************************/
        	function searchData(startRow, rowCount) {
	       	    var arrObjNm = getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/objNm").split("^"); 
	       	    if ( arrObjNm[0] == "" || arrObjNm == null || arrObjNm == undefined )  {
		       	    showMsg("C_I034");
		       	    return;
	       	    }
	       	    var BISComDspDatDTO = {BISComDspDatDTO:{}};
		        callProFrameSync(arrObjNm[0],arrObjNm[1],arrObjNm[2],BISComDspDatDTO, "BISComDspDatDTO","resp");
        	}
        	
        	/**************************************************************************
             * function    : setScreen
             * Description : 조회조건 폼 로딩, 그리드 정보 동적 생성, 
             * Parameter   : null
             * Return      : null
             **************************************************************************/
        	function setScreen() {
	       	    var arr = WebSquare.ModelUtil.findInstanceNodes( "respOutForm/root/message/BISComMetaDataDTO/BISComStatisticsLinkListDTO/BISComStatisticsLinkDTO" );
  	            var sOutputFormNo = getValue("respOutForm/root/message/BISComMetaDataDTO/BISComStatisticsLinkDTO[1]/outputFormNo");
	       	    
	       	    searchFormReading(getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/inquiryCondDspPathNm"),getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/descreptionDspPathNm"));
	            if (getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/displayUnitNm") == "") {
	            	//txtUnit.setValue( "(단위:%)" );
	            } else {
		            txtUnit.setValue( "(단위 : " + getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/displayUnitNm") +")" );
	            }
	            makeGrid(divisionNm);
	            var chartTyp = getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/chartTyp");
	            if(chartTyp == "") {
	            	grpChartBtn.setStyle( "display" , "none" );
	            	grpUnitExcel.changeClass( "gridBtnUp","gridBtnDn" );
	            } else {
	            	grpChartBtn.setStyle( "display" , "block" );
	            }
	            
	            if(sOutputFormNo == "BIS0018"){
	            	wfrmFooter.show("");
	            }
	            
	            resizeIframe();
	            searchData();
        	}
        	
            /**************************************************************************
             * function    : chartShow
             * Description : 챠트 속성 정보를 이용하여 챠트 구성
             * Parameter   : 
             * Return      : null
             **************************************************************************/
            function chartShow() {
                 var sXPath = "resp/root/message/BISComDspDatListDTO/BISComDspDatDTO";
                 
                 var arrSeries = [];
                 var arrData = [];
                 var arrType = [];
                 var chartType = "";
                 var category = "";
                 
                 var outputFormNo = getValue("respOutForm/root/message/BISComMetaDataDTO/BISComStatisticsLinkListDTO/BISComStatisticsLinkDTO[1]/outputFormNo");
                 
                 var gridInfoArr = WebSquare.ModelUtil.findInstanceNodes( "respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[outputFormNo='" + outputFormNo + "']" );
                 var headInfoArr = WebSquare.ModelUtil.findInstanceNodes( "respOutForm/root/message/BISComMetaDataDTO/BISComOutColHdrListDTO/BISComOutColHdrDTO[outputFormNo='" + outputFormNo + "']" );
                 var bodyInfoArr = WebSquare.ModelUtil.findInstanceNodes( "respOutForm/root/message/BISComMetaDataDTO/BISComOutDataColListDTO/BISComOutDataColDTO[outputFormNo='" + outputFormNo + "']" );
				 var bodyPropArr = WebSquare.ModelUtil.findInstanceNodes( "respOutForm/root/message/BISComMetaDataDTO/BISComOutColHdrBodyListDTO/BISComOutColHdrDTO[outputFormNo='" + outputFormNo + "']" );                 
                 
                 for (var i=0;i<bodyPropArr.length;i++) {
                    if (WebSquare.xml.getValue( bodyPropArr[i], "chartDatGb" ) == "2") {
                       arrSeries.push(WebSquare.xml.getValue( bodyInfoArr[i], "outputColCd" )+"|"+WebSquare.xml.getValue( bodyPropArr[i], "headerNm" ));
                    } else if (WebSquare.xml.getValue( bodyPropArr[i], "chartDatGb" ) == "3") {
                       arrData.push(WebSquare.xml.getValue( bodyInfoArr[i], "outputColCd" ));
                    } else if (WebSquare.xml.getValue( bodyPropArr[i], "chartDatGb" ) == "1") {
                       category = WebSquare.xml.getValue( bodyInfoArr[i], "outputColCd" );
                    }
                 }
                 
                 if (WebSquare.xml.getValue( gridInfoArr[0], "chartTyp" ) == "1") {
                    chartType = "line";
                 } else if (WebSquare.xml.getValue( gridInfoArr[0], "chartTyp" ) == "2") {
                    chartType = "bar";
                 } else { return; }
                 
                 /**option
                  **    type : chart type   (bar, line)
                  **    grpId : 챠트가 보여질 그룹ID
                  **    titile :챠트 타이틀
                  **    yLabel : y축 라벨
                  **    xPath  : 챠트의 정보를 가지고 있는 노드
                  **    category : 챠트의 정보중 카테고리에 해당하는 노드명
                  **    arrSeries : 챠트의 정보중 시리즈에 해당하는 노드명 배열
                  **    arrData : 챠트의 정보중 자료에 해당하는 노드명 배열      
                  **    arrType : Combo 챠트 일 경우 Series별 chart type (bar, line)
                  *****************************************************************/
                 var option = { type     : chartType,
                               grpId     : "grpChart",
                               title     : "",
                               yLabel    : [getValue("respOutForm/root/message/BISComMetaDataDTO/BISComOutFormListDTO/BISComOutFormDTO[1]/y1AxsLblNm")],
                               xPath     : sXPath,
                               category  : category,
                               arrSeries : arrSeries,
                               arrData   : arrData,     
                               arrType   : arrType          
                             }; 
                makeChart(option);  
            }
            
            /**************************************************************************
             * function    : chartReadingProc
             * Description : 챠트 hidden/Hide 처리
             * Parameter   : 
             * Return      : null
             **************************************************************************/
            function chartReadingProc() {
	            if (grpChart.getStyle( "display" ) == "block") {
		            imgChartBtn.setSrc( "/images/sub/graph_btn_off.gif" );
		            imgChartBtn.setAlt( "그래프열기" );
		            grpChart.setStyle( "display" , "none" );
		            grpUnitExcel.changeClass( "gridBtnDn","gridBtnUp" );
	            } else {
		            imgChartBtn.setSrc( "/images/sub/graph_btn_on.gif" );
		            imgChartBtn.setAlt( "그래프닫기" );
		            grpChart.setStyle( "display" , "block" );
		            grpUnitExcel.changeClass( "gridBtnUp","gridBtnDn" );
	            }
	     		resizeIframe();
            }
            
            /**************************************************************************
             * function    : gridLinkProc
             * Description : Body 컬럼 중 링크값이 있는 열에 대해 링크 처리
             * Parameter   : linkPage(링크할 페이지 경로)
             * Return      : null
             **************************************************************************/
            function gridLinkProc(row,col, linkPage, linkPagepopyn, linkPopwid, linkPophgt) {
            
               var strParam = "";
               var outputFormNo = getValue("respOutForm/root/message/BISComMetaDataDTO/BISComStatisticsLinkListDTO/BISComStatisticsLinkDTO[1]/outputFormNo");
               var bodyPropArr = WebSquare.ModelUtil.findInstanceNodes( "respOutForm/root/message/BISComMetaDataDTO/BISComOutColHdrListDTO/BISComOutColHdrDTO[outputFormNo='" + outputFormNo + "' and columnHdrgb='C']" );
               
               var headerId = WebSquare.xml.getValue( bodyPropArr[col] , "headerId" );
               var urlParamArr = WebSquare.ModelUtil.findInstanceNodes( "respOutForm/root/message/BISComMetaDataDTO/BISComOutUrlParamListDTO/BISComOutUrlParamDTO[outputFormNo='" + outputFormNo + "' and headerId='" + headerId + "']" );
               
               for (var i=0;i<urlParamArr.length;i++) {
                   //if (i==0) strParam = "?";
                   //else strParam += "&";
                   strParam += "&";
                   
                   //var colId = WebSquare.xml.getValue( bodyPropArr[col] , "parameterNm" );
                   var colId = WebSquare.xml.getValue( urlParamArr[i] , "parameterNm" );
                   strParam += colId + "=" + grdMain.getCellData( row , colId );
               }
               
               if (linkPagepopyn == "Y") {
                    if (linkPopwid == 0) linkPopwid = 500;
                    if (linkPophgt == 0) linkPophgt = 500;

                    openPopup2("", linkPage + strParam, 
                         { width      : linkPopwid || 500
                         , height     : linkPophgt || 500
                         , resizable  : false
                         , scrollbars : false } );
                         
                    return;
               }
               /*****************************************************************
                 - 공통 화면일 경우 싱글로 조회 하는 것과 탭메뉴 안에서 조회하는 화면으로 구분
                 - 탭메뉴 조회화면은 iframe을 이용하여 싱글 화면을 include 하는 방식이므로
                   parent는 싱글일때와 탭메뉴일때 다름.
                 - 싱글과 탭메뉴의 구분은 탭번호를 parameter에 존재 여부로 구분 가능
               *****************************************************************/
               if (linkPage.indexOf("http://") >= 0) {
                  window.open(linkPage + strParam);
               } else {
                  parent.fnTreeview_ondblclick("", linkPage);
               }
            }
            
            /**************************************************************************
             * function    : excelDownLoad
             * Description : 그리드의 내용을 엑셀로 다운로드
             * Parameter   : null
             * Return      : null
             **************************************************************************/
            function excelDownLoad(removeCol) {
            	if(typeof removeCol == "undefined"){
            		removeCol = "";
            	}
            	saveExcelDown(grdMain, divisionNm, "1", true, false, removeCol);
            }
